<template>
  <ResearchShell section="stock" :dark="darkMode" :busy="submitting" @new-analysis="newAnalysis">
    <div :class="['stock-lab', {'has-run':Boolean(run),'investors-view':view==='investors'}]">
      <header v-if="!run" class="stock-header"><div><h1>Stock Lab</h1><p>Choose a stock. Watch the agents. Explore its potential.</p></div><div class="stock-header-tools"><button class="stock-text-button" @click="toggleLibrary">Saved stock reports</button><button class="stock-text-button" :aria-pressed="darkMode" @click="darkMode=!darkMode">{{ darkMode?'Light mode':'Dark mode' }}</button></div></header>
      <div v-if="error" class="stock-error" role="alert">{{ error }}<button @click="error=''" aria-label="Dismiss error">Dismiss</button></div>

      <template v-if="!run && !loading">
        <StockWorkflowNav phase="ticker" @step="newAnalysis"/>
        <section class="stock-start">
          <form class="stock-form" @submit.prevent="startAnalysis">
            <h2>Which stock would you like to explore?</h2><p>Enter its ticker for company research, agent discussion and a one-year outlook.</p>
            <div class="stock-input-row ticker-first"><label>Stock ticker / code<input v-model="ticker" @input="recognizeMarket" required maxlength="12" :placeholder="market==='US'?'e.g. MSFT or NVDA':market==='HK'?'e.g. 0700.HK':market==='SH'?'e.g. 600519.SS':'e.g. 002518.SZ'" autocomplete="off" autocapitalize="characters" :disabled="submitting"></label></div>
            <details class="stock-extra listing-settings"><summary>Listing market & horizon</summary><div class="stock-input-row"><label for="stock-listing-market">Listing market<select id="stock-listing-market" aria-label="Listing market" v-model="market" :disabled="submitting"><option value="US">United States</option><option value="HK">Hong Kong</option><option value="SH">Shanghai</option><option value="SZ">Shenzhen</option></select></label><label>Investment horizon<select v-model="horizon" :disabled="submitting"><option value="days">Days</option><option value="weeks">Weeks</option><option value="months">Months</option><option value="years">One year</option></select></label></div></details>
            <details class="stock-extra"><summary>Add sources and research context</summary><label>What should the researchers investigate?<textarea v-model="notes" maxlength="6000" rows="3" placeholder="For example: will customers still need this product, and are reliability problems affecting retention?"/></label><label>Public source URLs <span>Optional · one per line, up to eight</span><textarea v-model="urls" rows="3" placeholder="Company reports, product tests or independent customer evidence"/></label><label v-if="market==='US'">SEC CIK <span>Optional · for a ticker outside the built-in US company list</span><input v-model="cik" inputmode="numeric" maxlength="10" placeholder="Company identifier"></label></details>
            <button class="stock-primary" type="submit" :disabled="submitting || !connection?.ready || !ticker.trim()">{{ submitting ? 'Starting research…' : 'Analyse stock' }}<ResearchIcon name="arrow"/></button>
            <p v-if="connection && !connection.ready" class="stock-subtle">{{ connection.message }}<button class="stock-text-button" type="button" @click="checkConnection">Check again</button></p>
            <p class="stock-form-note">Next: watch the research team and simulated investors discuss your stock.</p>
          </form>
          <aside class="stock-structure"><h3>From ticker to outlook</h3><ol><li><strong>Your company</strong><span>Products, demand, growth and valuation.</span></li><li><strong>An agent swarm</strong><span>Different perspectives, connected dots and recorded discussion.</span></li><li><strong>Your results</strong><span>Low, central and high projections, agent rating and stock-specific reasoning.</span></li></ol></aside>
        </section>
      </template>

      <p v-if="loading" class="stock-empty" role="status">Loading your saved analysis…</p>
      <template v-if="run&&simpleWorkspace">
        <StockWorkflowNav :run="run" :phase="workflowPhase" @step="changeWorkflowStep"/>
        <header class="stock-simple-heading"><div><p>{{ run.ticker }} · {{ marketName(run.market) }}</p><h1>{{ run.company||run.ticker }}</h1><span v-if="run.dossier?.price">Reported quote {{ money(run.dossier.price.value,run.dossier.price.currency) }} · {{ date(run.dossier.price.as_of) }}</span></div><div><button :aria-pressed="darkMode" @click="darkMode=!darkMode">{{ darkMode?'Light mode':'Dark mode' }}</button><details class="stock-research-menu"><summary>Research tools</summary><nav><button v-if="['failed','interrupted','cancelled'].includes(run.status)" :disabled="submitting" @click="resumeAnalysis">Continue saved work</button><button v-if="run.verdict" :disabled="submitting" @click="reassess">Reassess company</button><button :disabled="downloading" @click="downloadExport('markdown')">Export report</button><button @click="setView('company')">Company research</button><button @click="setView('sources')">Sources</button><RouterLink :to="{path:route.path,query:{details:'1'}}">Full research & tools</RouterLink></nav></details></div></header>
        <StockAnalysisPage v-if="workflowPhase==='analysis'" :run="run" @results="setView('overview')" @discussion="openStockAgents"/>
        <StockResults v-else :run="run" @analysis="setView('discussion')" @research="setView('company')" @annual="setView('annual')" @investors="setView('investors')" @sources="setView('sources')" @download="downloadExport('markdown')"><template #details><StockEvidenceResolution :run="run" :busy="submitting" @busy="submitting=$event" @started="openRun"/><StockDecisionFramework :run="run" :busy="submitting" @research="setView('company')" @reassess="reassess"/></template></StockResults>
      </template>
      <template v-if="run&&!simpleWorkspace">
        <section class="stock-run-heading" :class="{'investors-heading':view==='investors'}"><div><p class="stock-ticker">{{ run.ticker }} <span>· {{ marketName(run.market) }} · {{ run.horizon }} horizon</span></p><h1>{{ run.company }}</h1><p class="stock-subtle">Started {{ date(run.created_at) }}<template v-if="run.dossier?.price"> · Reported quote {{ money(run.dossier.price.value, run.dossier.price.currency) }} as of {{ date(run.dossier.price.as_of) }}</template></p></div><div class="stock-run-actions"><button v-if="isPendingAnalysis(run.status)" class="stock-secondary" @click="stopAnalysis">Stop run</button><button v-else-if="['failed','interrupted','cancelled'].includes(run.status)" class="stock-secondary" :disabled="submitting" @click="resumeAnalysis">Resume saved work</button><button v-if="['complete','complete_with_gaps'].includes(run.status)" class="stock-secondary" :disabled="submitting" @click="reassess">Reassess company</button><button class="stock-secondary" :disabled="downloading" @click="downloadExport('markdown')">Export report</button><button class="stock-secondary" :disabled="downloading" @click="downloadExport('json')">JSON</button></div></section>
        <StockEvidenceResolution v-if="view==='overview'" :run="run" :busy="submitting" @busy="submitting=$event" @started="openRun"/>
        <StockJourney v-if="view!=='investors'&&view!=='discussion'&&(!isPendingAnalysis(run.status)||view!=='overview')" :run="run"/>
        <p v-if="run.agent_errors?.length" class="stock-error" role="status"><template v-if="isPendingAnalysis(run.status)">Some responses were unavailable. The remaining analysis continues; affected conclusions remain withheld.</template><template v-else-if="run.status==='complete_with_gaps'">Your report is ready with disclosed gaps. Inspect the saved findings or retry missing work before relying on affected conclusions.</template><template v-else-if="['failed','interrupted','cancelled'].includes(run.status)">Some responses were unavailable. Resume saved work to retry unfinished tasks; completed findings remain inspectable.</template><template v-else>Some responses were unavailable. Inspect the disclosed gaps before relying on affected conclusions.</template></p>
        <div class="stock-report-navigation">
          <nav class="stock-tabs" aria-label="Report navigation"><button v-for="tab in reportSections" :key="tab.id" :aria-current="isReportSection(tab.id) ? 'page' : undefined" :class="{selected:isReportSection(tab.id)}" @click="openReportSection(tab.id)">{{ tab.name }}</button></nav>
          <nav v-if="secondaryTabs.length" class="stock-subtabs" aria-label="Research views"><button v-for="tab in secondaryTabs" :key="tab.id" :aria-current="view === tab.id ? 'page' : undefined" :class="{selected:view === tab.id}" @click="setView(tab.id)">{{ tab.name }}</button></nav>
        </div>

        <section v-if="view==='overview'" class="stock-overview">
          <StockDecisionFramework v-if="!isPendingAnalysis(run.status)" :run="run" :busy="submitting" @research="setView('company')" @reassess="reassess"/>
          <AnalysisOverview swarm v-if="isPendingAnalysis(run.status)||!run.verdict" :run="run" :overview="stockOverview(run)" @discussion="openStockAgents"><template #chart><StockPriceContext :run="run" terminal/></template></AnalysisOverview>
          <template v-else>
          <StockOutlook :run="run" compact :busy="submitting" @generate="addOutlook" @open-debate="setView('annual')"/>
          <div class="stock-summary-workspace"><StockPriceContext :run="run" terminal/><div v-if="run.verdict" class="stock-verdict">
            <div class="verdict-heading"><h2>{{ verdictLabel(run.verdict.verdict) }}</h2><span>Evidence: {{ run.verdict.evidence_strength }}</span></div>
            <p class="verdict-summary"><StockEvidenceText :text="shortSummary(run.verdict.summary)" :sources="run.dossier?.sources || []"/></p>
            <div class="verdict-sides"><section><h3 class="positive">Why consider it?</h3><ul><li v-for="claim in run.verdict.supporting.slice(0,2)" :key="claim.text"><StockEvidenceText :text="claim.text" :sources="run.dossier?.sources || []"/></li></ul></section><section><h3 class="negative">Why be cautious?</h3><ul><li v-for="claim in run.verdict.opposing.slice(0,2)" :key="claim.text"><StockEvidenceText :text="claim.text" :sources="run.dossier?.sources || []"/></li></ul></section></div>
            <div class="summary-actions"><button class="stock-secondary" @click="setView('company')">Read company research</button><button class="stock-secondary" @click="setView('annual')">Compare the one-year arguments</button><button class="stock-secondary" @click="setView('investors')">See what investors decided</button></div>
            <details class="summary-detail"><summary>Business and valuation details</summary><div class="verdict-assessments"><section><h3>The business</h3><p><StockEvidenceText :text="run.verdict.business_assessment" :sources="run.dossier?.sources || []"/></p></section><section><h3>The stock price</h3><p><StockEvidenceText :text="run.verdict.price_assessment" :sources="run.dossier?.sources || []"/></p></section></div><p><StockEvidenceText :text="run.verdict.summary" :sources="run.dossier?.sources || []"/></p></details>
            <details class="summary-detail"><summary>What would change the verdict?</summary><div class="verdict-assessments"><section><h3>What would change this verdict</h3><ul><li v-for="item in run.verdict.change_conditions" :key="item">{{ item }}</li></ul></section></div></details>
            <p class="stock-research-limit">The one-year outlook is a valuation estimate. The virtual market shows investor reactions under assumptions; its short clearing rounds are not a one-year forecast.</p>
          </div>
          </div><details class="stock-run-log"><summary>Explore the research agents & investor messages</summary><AnalysisOverview swarm :run="run" :overview="stockOverview(run)" @discussion="openStockAgents"><template #chart><StockPriceContext :run="run" terminal/></template></AnalysisOverview></details></template>
          <section v-if="run.evidence_review" class="stock-evidence-note"><h3>Evidence checker</h3><p><StockEvidenceText :text="run.evidence_review.assessment" :sources="run.dossier?.sources || []"/></p></section>
          <details class="stock-run-log"><summary>Run activity · {{ run.events?.length||0 }} recorded events</summary><ol><li v-for="(item,i) in [...(run.events||[])].reverse().slice(0,50)" :key="i"><time>{{ new Date(item.at).toLocaleTimeString('en-AU',{hour:'2-digit',minute:'2-digit',second:'2-digit'}) }}</time>{{ item.message }}</li></ol></details>
        </section>

        <section v-if="view==='discussion'" class="stock-discussion"><AnalysisOverview swarm :run="run" :overview="stockOverview(run)" @discussion="openStockAgents"><template #chart><StockPriceContext :run="run" terminal/></template></AnalysisOverview></section>
        <template v-if="view==='company'"><div class="research-map-toggle"><button class="stock-text-button" :aria-expanded="showResearchMap" @click="showResearchMap=!showResearchMap">{{ showResearchMap?'Hide research agent graph':'Explore research agents' }}</button></div><AnalysisOverview swarm v-if="showResearchMap" :run="run" :overview="stockOverview(run)" @discussion="openStockAgents"/><StockResearchGraph v-if="showResearchMap&&!run.execution_profile" :run="run"/><StockResearch :run="run" :items="catalog?.company_areas||[]" layer="company"/></template>
        <StockResearch v-if="view==='strategy'" :run="run" :items="catalog?.strategies || []" layer="strategy"/>
        <section v-if="view==='investors'" class="stock-investors-wide"><StockInvestors compact :run-id="run.id" :status="run.status" :people="run.investors||[]" :rounds="run.investor_rounds||{}" :sources="run.dossier?.sources||[]" :currency="run.dossier?.price?.currency||'USD'"/><details class="investor-price-details"><summary>Price context & market scenarios</summary><StockPriceContext :run="run" terminal/><p class="stock-investor-context">Each investor keeps its own portfolio, strategy, risk limits and decision memory. Recorded discussion is separate from market fills.</p><button class="stock-secondary" @click="setView('market')">Compare the market scenarios →</button></details></section>
        <p v-if="['market','investors'].includes(view)&&run.resolution?.investor_refresh_withheld" class="stock-investor-context">Historical saved investor/market output · the current quote or evidence is unverified, so no refreshed numerical simulation is offered.</p><template v-if="view==='market'"><details class="stock-run-log" open><summary>Investor discussion context · recorded messages, separate from market fills</summary><StockInvestorConversation :run-id="run.id+'-market-context'" @discussion="setView('investors')" :status="run.status" :people="run.investors||[]" :rounds="run.investor_rounds||{}"/></details></template><StockMarket v-if="view==='market'" :scenarios="run.scenarios || []" :reference="run.resolution?.investor_refresh_withheld?(run.resolution.previous_price?.value||run.dossier?.price?.value):run.dossier?.price?.value" :currency="run.dossier?.price?.currency||'USD'"/>

        <StockDecisionFramework v-if="view==='annual'" :run="run" :busy="submitting" @research="setView('company')" @reassess="reassess"/>
        <StockOutlook v-if="view==='annual'" :run="run" :busy="submitting" @generate="addOutlook"/>
        <section v-if="view==='sources'">
          <div class="stock-section-heading"><div><h2>Evidence and calculated metrics</h2><p>Captured sources keep their dates and provenance.</p></div><span class="stock-subtle">{{ run.dossier?.sources.length || 0 }} sources</span></div>
          <p v-if="!run.dossier" class="stock-empty">Sources are being collected.</p>
          <template v-else><div class="stock-table-wrap"><table class="stock-table metrics-table"><thead><tr><th>Metric</th><th>Reported/calculated value</th><th>Period or basis</th></tr></thead><tbody><tr v-for="(metric,key) in availableMetrics(run.dossier.metrics)" :key="key"><td>{{ metricName(key) }}</td><td>{{ metric.unit==='ratio' ? percent(metric.val) : number(metric.val) }}<span v-if="metric.unit!=='ratio'" class="stock-subtle"> {{ metric.unit }}</span></td><td>{{ metric.end || metric.basis || 'Derived from supplied price series' }}</td></tr></tbody></table></div><article v-for="item in run.dossier.sources" :key="item.id" class="stock-source"><h3><a v-if="item.url.startsWith('http')" :href="item.url" target="_blank" rel="noopener noreferrer">{{ item.title }}<ResearchIcon name="external"/></a><span v-else>{{ item.title }}</span></h3><p>{{ sourceKind(item.kind) }}<template v-if="item.published_at"> · Published {{ date(item.published_at) }}</template> · Retrieved {{ date(item.retrieved_at) }}</p><details><summary>Inspect captured source text</summary><pre>{{ item.content }}</pre></details></article></template>
        </section>
      </template>

      <section v-if="history.length && (!run || showLibrary)" id="stock-history" class="stock-history"><div class="stock-section-heading"><div><h2>Saved stock research</h2><p>Open a previous run or reassess a completed company with its investor portfolios.</p></div><button class="stock-text-button" @click="loadHistory">Refresh</button></div><div class="stock-table-wrap"><table class="stock-table"><thead><tr><th>Company</th><th>Horizon</th><th>Created</th><th>Result</th></tr></thead><tbody><tr v-for="item in history" :key="item.id"><td><button class="stock-text-button" @click="openRun(item.id)">{{ item.company }} <span class="stock-subtle">{{ item.ticker }} · {{ marketName(item.market) }}</span></button></td><td>{{ item.horizon }}</td><td>{{ date(item.created_at) }}</td><td>{{ item.verdict ? verdictLabel(item.verdict) : (item.status||'saved').replaceAll('_',' ') }}</td></tr></tbody></table></div></section>
      <footer class="stock-footer">MiroFish · Stock Lab · Saved research and simulated portfolios · GPT-6 Luna</footer>
    </div>
  </ResearchShell>
</template>

<script setup>
import { computed, nextTick, onBeforeUnmount, onMounted, ref, watch } from 'vue'
import { useRoute, useRouter } from 'vue-router'
import ResearchShell from '../components/ResearchShell.vue'
import ResearchIcon from '../components/ResearchIcon.vue'
import StockResearch from '../components/StockResearch.vue'
import StockInvestorConversation from '../components/StockInvestorConversation.vue'
import StockInvestors from '../components/StockInvestors.vue'
import StockEvidenceResolution from '../components/StockEvidenceResolution.vue'
import StockPriceContext from '../components/StockPriceContext.vue'
import AnalysisOverview from '../components/AnalysisOverview.vue'
import {stockOverview} from '../utils/stockAnalysisOverview.mjs'
import StockResearchGraph from '../components/StockResearchGraph.vue'
import StockMarket from '../components/StockMarket.vue'
import StockEvidenceText from '../components/StockEvidenceText.vue'
import StockJourney from '../components/StockJourney.vue'
import StockDecisionFramework from '../components/StockDecisionFramework.vue'
import StockOutlook from '../components/StockOutlook.vue'
import StockWorkflowNav from '../components/StockWorkflowNav.vue'
import StockAnalysisPage from '../components/StockAnalysisPage.vue'
import StockResults from '../components/StockResults.vue'
import {stockWorkflowPhase} from '../utils/stockResultsView.mjs'
import {swarmPollInterval} from '../utils/stockSwarm.mjs'
import { stockSections, researchViews, simulationViews, stockSection, stockDestination } from '../utils/stockFlow.mjs'
import { stockRequest, exportUrl, money, number, percent, date } from '../api/stocklab'
import {progressDelay} from '../utils/plans.mjs'
import {account,downloadPrivateFile,initializeAccount,refreshAccount,publicMode} from '../api/platform'
import {isPendingAnalysis} from '../utils/platform.mjs'
import {requireAnalysisResponse,requireHistoryResponse} from '../utils/analysisResponses.mjs'
import {availableMetrics} from '../utils/availableEvidence.mjs'

const route = useRoute(), router = useRouter()
const run = ref(null), catalog = ref(null), connection = ref(null), history = ref([]), error = ref('')
const darkMode=ref(true)
const market=ref('US')
const marketName=value=>({US:'United States',HK:'Hong Kong',SH:'Shanghai',SZ:'Shenzhen'}[value]||'United States')
function recognizeMarket(){const value=ticker.value.trim().toUpperCase(),suffix=value.match(/\.(HK|SS|SZ)$/)?.[1];if(suffix)market.value=({HK:'HK',SS:'SH',SZ:'SZ'})[suffix];else if(/^\d{1,5}$/.test(value))market.value='HK';else if(/^\d{6}$/.test(value))market.value=/^[69]/.test(value)?'SH':'SZ';else if(/^[A-Z]/.test(value))market.value='US'}
const ticker = ref(''), horizon = ref('years'), notes = ref(''), urls = ref(''), cik = ref('')
const downloading=ref(false)
const submitting = ref(false), loading = ref(false), showLibrary = ref(false), showResearchMap=ref(false)
let timer, generation = 0, disposed = false, navObserver
function openStockAgents(lens){if(lens==='traders')setView('investors');else{showResearchMap.value=true;setView('company')}}
const reportSections=[{id:'overview',name:'Results'},{id:'discussion',name:'Discussion'},...stockSections.filter(tab=>tab.id!=='overview'&&(!publicMode||tab.id!=='simulation'))]
const allViews=['overview','discussion','company','strategy','annual','investors','market','sources']
const view = computed(() => allViews.includes(route.query.view)&&(!publicMode||route.query.view!=='market') ? route.query.view : 'overview')
const simpleWorkspace=computed(()=>route.query.details!=='1'&&['overview','discussion'].includes(view.value))
const workflowPhase=computed(()=>stockWorkflowPhase(run.value,view.value==='discussion'?'analysis':'results'))
function changeWorkflowStep(step){if(step==='ticker')newAnalysis();else setView(step==='analysis'?'discussion':'overview')}
const section = computed(() => stockSection(view.value))
const isReportSection=id=>view.value==='discussion'?id==='discussion':section.value===id
function openReportSection(id){setView(id==='discussion'?'discussion':id==='overview'?'overview':stockDestination(id,view.value))}
const secondaryTabs = computed(() => section.value==='research'?researchViews:section.value==='simulation'?simulationViews:[])
const shortSummary = text => text.split(/(?<=[.!?])\s+/).slice(0,2).join(' ')
async function downloadExport(format){if(downloading.value)return;downloading.value=true;try{await downloadPrivateFile(exportUrl(run.value.id,format),`stock-research-${run.value.ticker}.${format==='markdown'?'md':'json'}`)}catch(e){error.value=e.message}finally{downloading.value=false}}
async function toggleLibrary() { showLibrary.value=!showLibrary.value; if(showLibrary.value){await loadHistory();await nextTick();document.getElementById('stock-history')?.scrollIntoView({behavior:'smooth',block:'start'})} }
const source = id => run.value?.dossier?.sources.find(s => s.id === id)
const count = layer => run.value?.research.filter(r => r.layer === layer && r.result).length || 0
const verdictLabel = value => ({attractive:'Attractive at the reported price',watch:'Watch',avoid:'Avoid',insufficient_evidence:'Insufficient evidence'})[value] || value
const metricName = value => value.replaceAll('_',' ').replace(/^./, c => c.toUpperCase())
const sourceKind = value => ({sec_financials:'SEC reported financial facts',sec_filing:'SEC filing',sec_filing_history:'SEC filing metadata',reported_financials:'Reported financials · financial-data aggregator',market_data:'Public quote / daily price data',web_article:'Captured web article',user_supplied_unverified:'Your context · not independently verified'})[value] || value

async function checkConnection() { try { if(publicMode){await initializeAccount({retry:true});await refreshAccount();connection.value={...account.config.provider,...(!account.config.analyses_enabled&&!account.info?.entitlement?.developer?{ready:false,message:'Public analyses are not open yet. Your saved research remains accessible.'}:{})}}else connection.value=(await stockRequest('/state')).connection } catch(e) { error.value=e.message } }
async function loadHistory() { try { history.value=requireHistoryResponse(await stockRequest('/analyses')) } catch(e) { error.value=e.message } }
let progressRevision=-1,progressRunId=''
async function loadRun(id, token) {
  if (disposed || token!==generation) return
  try {
    if(progressRunId!==id){progressRevision=-1;progressRunId=id}
    let result
    if(publicMode&&run.value?.id===id&&isPendingAnalysis(run.value.status)&&['overview','discussion'].includes(view.value)){
      const update=await stockRequest('/analyses/'+id+'/progress?after_revision='+progressRevision)
      if(disposed||token!==generation)return
      if(update.unchanged){timer=setTimeout(()=>loadRun(id,token),progressDelay(run.value.status,document.hidden));return}
      progressRevision=update.revision
      result=update.complete?await stockRequest('/analyses/'+id):update
    }else result=await stockRequest('/analyses/'+id)
    if (disposed || token!==generation) return
    run.value=requireAnalysisResponse(result,id);loading.value=false;error.value=''
    if (isPendingAnalysis(run.value.status)) timer=setTimeout(()=>loadRun(id,token),publicMode?progressDelay(run.value.status,document.hidden):swarmPollInterval(run.value.status,view.value))
    else loadHistory()
  } catch(e) {
    if (token!==generation || disposed) return
    error.value=e.message;loading.value=false
    if ((!run.value||isPendingAnalysis(run.value.status))&&![401,403,404].includes(e.status)) timer=setTimeout(()=>loadRun(id,token),4000)
  }
}
async function openRun(id) { await router.push('/stock-lab/'+id) }
function setView(id) { if(!allViews.includes(id)||id===view.value)return;router.push({path:route.path,query:id==='overview'?{}:{view:id}}) }
function newAnalysis() { if(submitting.value)return;router.push('/stock-lab');run.value=null;error.value='' }
async function startAnalysis() {
  if(submitting.value||!connection.value?.ready)return
  submitting.value=true;error.value=''
  try { const result=await stockRequest('/analyses',{method:'POST',body:JSON.stringify({ticker:ticker.value.trim().toUpperCase(),market:market.value,horizon:horizon.value,notes:notes.value,source_urls:urls.value.split('\n').map(s=>s.trim()).filter(Boolean),cik:market.value==='US'?cik.value||null:null})});await openRun(result.id) }
  catch(e){error.value=e.message}
  finally{submitting.value=false}
}
async function addOutlook() { if(submitting.value)return;submitting.value=true;error.value='';try{const result=await stockRequest('/analyses/'+run.value.id+'/one-year',{method:'POST'});clearTimeout(timer);if(result.id&&result.id!==run.value.id)await openRun(result.id);else await loadRun(run.value.id,generation)}catch(e){error.value=e.message}finally{submitting.value=false} }
async function stopAnalysis() { try {await stockRequest('/analyses/'+run.value.id+'/cancel',{method:'POST'})}catch(e){error.value=e.message} }
async function resumeAnalysis() { if(submitting.value)return;submitting.value=true;try{const result=await stockRequest('/analyses/'+run.value.id+'/resume',{method:'POST'});clearTimeout(timer);if(result.id&&result.id!==run.value.id)await openRun(result.id);else await loadRun(run.value.id,generation)}catch(e){error.value=e.message}finally{submitting.value=false} }
async function reassess() { if(submitting.value)return;submitting.value=true;try{const result=await stockRequest('/analyses',{method:'POST',body:JSON.stringify({ticker:run.value.ticker,market:run.value.market,horizon:run.value.horizon,cik:run.value.cik,source_urls:run.value.source_urls,notes:run.value.notes,parent_id:run.value.id})});await openRun(result.id)}catch(e){error.value=e.message}finally{submitting.value=false} }
watch(()=>route.params.runId,id=>{clearTimeout(timer);generation++;run.value=null;showLibrary.value=false;showResearchMap.value=false;error.value='';if(id){loading.value=true;loadRun(id,generation)}else{loading.value=false;loadHistory()}},{immediate:true})
onMounted(async()=>{const sidebar=document.querySelector('.research-sidebar');if(sidebar){navObserver=new ResizeObserver(()=>{document.querySelector('.stock-lab')?.style.setProperty('--stock-nav-top',matchMedia('(max-width:800px)').matches?Math.ceil(sidebar.getBoundingClientRect().height)+'px':'0px')});navObserver.observe(sidebar)}try{catalog.value=await stockRequest('/catalog')}catch(e){error.value=e.message}await checkConnection();await loadHistory()})
onBeforeUnmount(()=>{disposed=true;generation++;clearTimeout(timer);navObserver?.disconnect()})
</script>

